<?php require 'config.php'; $d=input();$s=$pdo->prepare('SELECT id,password FROM users WHERE email=? LIMIT 1');$s->execute([trim($d['email']??'')]);$u=$s->fetch(PDO::FETCH_ASSOC);if(!$u||!password_verify($d['password']??'',$u['password']))respond(['success'=>false,'message'=>'Incorrect email or password.'],401);$_SESSION['user_id']=(int)$u['id'];respond(['success'=>true,'user_id'=>$_SESSION['user_id']]);
